html:
{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{% import "costeo_yelke/templates/print/membrete.html" as m %}
{% import "costeo_yelke/templates/print/om_ficha.html" as om %}
{#- Orden de manufactura GENERAL de un producto: la ficha completa, con todo lo que se
    capturó para todos los talleres (procesos, tejidos, tablas, archivos…), para
    revisarla antes de mandarla. Cada taller recibe la suya filtrada en «Orden de
    Manufactura» (la de su orden de compra). Datos: om_general.om_general_registro. -#}
{%- set g = om_general_registro(doc.name) -%}
{{ oc.estilos() }}
{{ om.estilos() }}
{% if not no_letterhead %}
<div id="header-html" class="hidden-pdf"><div class="letter-head">{{ m.encabezado(g.encabezado, "Orden de manufactura general") }}</div></div>
{% endif %}
<div class="pdf-container">
<table class="yk-ficha">
    <tr><td class="k">Costeo</td><td class="v">{{ g.encabezado.costeo }}</td><td class="k">Cliente</td><td class="v">{{ g.encabezado.cliente or "" }}</td></tr>
    <tr><td class="k">Orden de venta</td><td class="v">{{ g.encabezado.sales_order or "—" }}</td><td class="k">Talleres</td><td class="v">{{ g.encabezado.talleres or "" }}</td></tr>
</table>
{{ om.ficha(g.registro) }}
{{ oc.pie("Vista general: cada taller recibe solo lo que se le asignó.") }}
</div>
{% if not no_letterhead %}
<div id="footer-html" class="visible-pdf"><div class="letter-head-footer">{{ m.pie(g.encabezado) }}</div></div>
{% endif %}
